SELECT "nct", "author", "year", "pubmed_id", "trial_name", "cancer_type", "treatment_regimen", "ici_name", "ici_class", "therapy_modality", "combination_type", "control_regimen", "control_type", "lines_of_treatment", "clinical_setting_in_relation_to_surgery", "primary_endpoint", "secondary_endpoint" FROM public."clinical_trials" WHERE "cancer_type" ILIKE '%Non-Small Cell Lung%' AND "lines_of_treatment" >= 2 AND "therapy_type" = 'Combination therapy'